<Base title="Neighborhoods" active="Neighborhoods" description="Area guides and subdivision profiles from people who live here.">
  <section class="band hero">
    <div class="wrap">
      <p class="eyebrow">Around town</p>
      <h1 style="margin-bottom:12px;max-width:900px">Find the neighborhood that fits your life.</h1>
      <p class="lead" style="margin-bottom:28px">A local perspective on where to eat, what to do, and what it is like to live there.</p>
      <p style="font-size:13px;font-weight:700;margin-bottom:10px">Start with what you love</p>
      <div class="tabs" id="n-loves" style="margin-bottom:24px"><button class="chip on" data-l="" aria-pressed="true">Anything</button>{loves.map(([k, l]) => <button class="chip" data-l={k} aria-pressed="false">{l}</button>)}</div>
      <p style="font-size:13px;font-weight:700;margin-bottom:10px">Or search an area</p>
      <div class="card pad search"><label class="sr" for="n-q">Search an area</label><input id="n-q" type="search" placeholder="Try Sugar Land, Montrose, or Cinco Ranch" /></div>
      <div class="tabs" id="n-regions" style="margin-top:20px"><button class="chip on" data-r="" aria-pressed="true">All</button>{regions.map((r) => <button class="chip" data-r={r} aria-pressed="false">{r}</button>)}</div>
    </div>
  </section>
  <section class="band">
    <div class="wrap">
      <p class="meta" id="n-count" style="margin-bottom:16px">{list.length} areas</p>
      <div class="grid g3">
        {list.map(({ p, biz, subs }) => (
          <div class="card tcard n-item" data-region={p.region} data-name={p.name.toLowerCase()} data-text={text(p)}>
            <a href={href(p)}>
              <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px"><span class="tag">{p.type}</span>{p.region && <span class="tag soft">{p.region}</span>}</div>
              <h4 style="margin-bottom:8px">{p.name}</h4>
              <p class="meta" style="margin-bottom:12px">{p.summary}</p>
              <p class="meta"><b>{biz}</b> places reviewed, <b>{subs}</b> subdivisions</p>
            </a>
            <div style="padding:0 24px 20px"><button class="chip cmp" type="button" data-n={p.name} aria-pressed="false">Compare</button></div>
          </div>
        ))}
      </div>
      <div class="card pad hidden" id="n-empty"><b>No areas match yet.</b><p class="meta" style="margin-top:4px">Try another name, region, or interest.</p></div>
    </div>
  </section>
  <section class="band tint" id="compare">
    <div class="wrap">
      <p class="eyebrow">Compare</p><h2 style="margin-bottom:8px">Side by side, in plain language</h2>
      <p class="meta" id="cmp-hint" style="margin-bottom:20px">Tap Compare on two or three areas above.</p>
      <div id="cmp-out" class="card hidden" style="overflow:auto"></div>
    </div>
  </section>
  <section class="band butter">
    <div class="wrap" style="display:flex;justify-content:space-between;align-items:center;gap:32px;flex-wrap:wrap">
      <div style="max-width:700px"><p class="eyebrow" style="color:var(--navy)">A neighbor to ask</p><h3 style="margin-bottom:8px">Curious about living somewhere?</h3><p style="font-size:17px">Dillon is a local Realtor who loves these neighborhoods. Questions are always welcome, with no pressure.</p></div>
      <a class="btn" href={url('/ask-dillon')}>Ask Dillon</a>
    </div>
  </section>
  <Prefs />
  <script is:inline define:vars={{ COMPARE: compare }}>
    (function () {
      var PRIOR = { food: ['restaurant', 'food', 'coffee', 'dining', 'cafe', 'eat'], parks: ['park', 'trail', 'green', 'yard', 'space', 'lake', 'outdoor', 'nature'], schools: ['school', 'isd', 'families', 'family'], commute: ['commute', 'downtown', 'freeway', 'minutes', 'central', 'close to', 'galleria', 'medical center', 'energy corridor'], quiet: ['quiet', 'peaceful', 'tucked', 'established', 'tree', 'private', 'calm', 'small town', 'laid back'], walk: ['walkable', 'walk', 'lively', 'nightlife', 'urban', 'inner loop', 'inside the loop', 'bike', 'townhome'], newer: ['new construction', 'new build', 'newer', 'master planned', 'new homes', 'developing', 'growing'], value: ['affordable', 'value', 'budget', 'starter', 'price'] };
      var $ = function (id) { return document.getElementById(id); };
      var q = $('n-q'), items = [].slice.call(document.querySelectorAll('.n-item')), region = '', love = '', picks = [];
      function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]; }); }
      function matches(i) { if (!love) return true; var t = i.dataset.text; return PRIOR[love].some(function (w) { return t.indexOf(w) > -1; }); }
      function run() {
        var t = q.value.trim().toLowerCase(), n = 0;
        items.forEach(function (i) { var ok = (!region || i.dataset.region === region) && (!t || i.dataset.name.indexOf(t) > -1) && matches(i); i.classList.toggle('hidden', !ok); if (ok) n++; });
        $('n-count').textContent = n + (n === 1 ? ' area' : ' areas'); $('n-empty').classList.toggle('hidden', n > 0);
      }
      function wire(id, attr, set) { $(id).addEventListener('click', function (e) { var b = e.target.closest('button'); if (!b) return; set(b.dataset[attr]); [].forEach.call(this.children, function (c) { c.classList.toggle('on', c === b); c.setAttribute('aria-pressed', c === b ? 'true' : 'false'); }); run(); }); }
      q.addEventListener('input', run);
      wire('n-regions', 'r', function (v) { region = v; }); wire('n-loves', 'l', function (v) { love = v; });
      var ROWS = [['Region', 'r'], ['Best for', 'b'], ['Typical homes', 'h'], ['Schools', 's'], ['Places we reviewed', 'biz'], ['Subdivision guides', 'subs']];
      function drawCompare() {
        document.querySelectorAll('.cmp').forEach(function (b) { var on = picks.indexOf(b.dataset.n) > -1; b.classList.toggle('on', on); b.setAttribute('aria-pressed', on ? 'true' : 'false'); b.textContent = on ? 'Comparing' : 'Compare'; });
